import "server-only";

import swordShieldCatalog from "@/data/generated/sword-shield/catalog.json";
import swordShieldMoves from "@/data/generated/sword-shield/moves.json";
import type { VersionGroupId } from "@/features/games/config";
import type { CatalogEntry, CatalogForm, GameCatalog, MoveIndex } from "@/types/domain";

import type { CardEntry } from "./catalog-context";

/**
 * Static catalogs generated by `pnpm data:generate`. Adding a game means
 * generating its files and registering them here.
 */
const CATALOGS: Record<VersionGroupId, GameCatalog> = {
  "sword-shield": swordShieldCatalog as GameCatalog,
};

const MOVE_INDEXES: Record<VersionGroupId, MoveIndex> = {
  "sword-shield": swordShieldMoves as MoveIndex,
};

export function getCatalog(versionGroup: VersionGroupId): GameCatalog {
  return CATALOGS[versionGroup];
}

export function getMoveIndex(versionGroup: VersionGroupId): MoveIndex {
  return MOVE_INDEXES[versionGroup];
}

export interface ResolvedEntry {
  entry: CatalogEntry;
  form: CatalogForm;
}

/**
 * Resolves a URL slug to a catalog entry and form. A species slug selects the
 * display form; a form slug (e.g. `meowth-galar`) selects that form.
 */
export function resolveEntry(versionGroup: VersionGroupId, slug: string): ResolvedEntry | null {
  const { entries } = getCatalog(versionGroup);
  for (const entry of entries) {
    if (entry.slug === slug) {
      const form = entry.forms.find((f) => f.id === entry.artId) ?? entry.forms[0];
      return form ? { entry, form } : null;
    }
    const form = entry.forms.find((f) => f.slug === slug);
    if (form) return { entry, form };
  }
  return null;
}

/** Card-sized catalog for the client: drops data only the detail page needs. */
export function getCardEntries(versionGroup: VersionGroupId): CardEntry[] {
  return getCatalog(versionGroup).entries.map((e) => ({
    id: e.id,
    slug: e.slug,
    name: e.name,
    types: e.types,
    artId: e.artId,
    dex: e.dex,
    availability: e.availability,
    legendary: e.legendary,
    mythical: e.mythical,
  }));
}

export interface Neighbor {
  slug: string;
  name: string;
  number: number;
}

/**
 * Previous/next species in the first regional dex that lists the entry
 * (national order for species outside every regional dex).
 */
export function getNeighbors(
  versionGroup: VersionGroupId,
  dexOrder: string[],
  speciesId: number,
): { dex: string | null; previous: Neighbor | null; next: Neighbor | null } {
  const { entries } = getCatalog(versionGroup);
  const entry = entries.find((e) => e.id === speciesId);
  if (!entry) return { dex: null, previous: null, next: null };
  const dex = dexOrder.find((id) => entry.dex[id] !== undefined) ?? null;
  const numberOf = (e: CatalogEntry) => (dex ? (e.dex[dex] ?? Infinity) : e.id);
  const list = entries
    .filter((e) => (dex ? e.dex[dex] !== undefined : Object.keys(e.dex).length === 0))
    .sort((a, b) => numberOf(a) - numberOf(b));
  const index = list.findIndex((e) => e.id === speciesId);
  const toNeighbor = (e: CatalogEntry | undefined): Neighbor | null =>
    e ? { slug: e.slug, name: e.name, number: numberOf(e) } : null;
  return { dex, previous: toNeighbor(list[index - 1]), next: toNeighbor(list[index + 1]) };
}
